  f.Close();mainWindow.Close();var psi=new ProcessStartInfo("dotnet"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};psi.ArgumentList.Add(Assembly.GetExecutingAssembly().Location);psi.ArgumentList.Add(p.Id);using var child=Process.Start(psi)!;var stdout=child.StandardOutput.ReadToEndAsync();var stderr=child.StandardError.ReadToEndAsync();Check(child.WaitForExit(90000),"Novo processo encerra");Console.Write(stdout.GetAwaiter().GetResult());Console.Write(stderr.GetAwaiter().GetResult());Check(child.ExitCode==0,"Persistencia integral contrato e reimpressao por movimento em NOVO PROCESSO");Console.WriteLine("PASS RECIBOS/CONTRATOS "+checks+" verificacoes Windows");
